-- stock_in_records: Inventory module requires this object for stock state, movements, or analytics.
CREATE TABLE IF NOT EXISTS public.stock_in_records (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  branch_id INTEGER REFERENCES public.branches(id),
  item_id TEXT,
  item_name TEXT,
  quantity NUMERIC(15,3) NOT NULL DEFAULT 0,
  unit_cost NUMERIC(15,2) DEFAULT 0,
  source_document TEXT,
  received_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- store_dispatches: Dispatch, OTP, transfer, or branch receiving workflow requires this object.
CREATE TABLE IF NOT EXISTS public.store_dispatches (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  dispatch_number TEXT UNIQUE,
  branch_id INTEGER REFERENCES public.branches(id),
  request_id UUID,
  status TEXT NOT NULL DEFAULT 'draft',
  otp_code TEXT,
  otp_expires_at TIMESTAMPTZ,
  dispatched_by UUID,
  dispatched_at TIMESTAMPTZ,
  received_by UUID,
  received_at TIMESTAMPTZ,
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Compatibility views for known legacy names.

CREATE OR REPLACE VIEW public.supplier_invoices WITH (security_invoker = true) AS
SELECT * FROM public.store_supplier_invoices;

CREATE OR REPLACE VIEW public.bar_stock_ledger WITH (security_invoker = true) AS
SELECT * FROM public.branch_stock_movements;